<?php namespace ProcessWire; ?>
<?php if($success):?><div class="form-success" role="status" tabindex="-1"><strong>Děkujeme za důvěru.</strong><p>Vaši poptávku jsme přijali a ozveme se vám co nejdříve.</p></div><?php endif;?>
<?php if($errors):?><div class="form-errors" role="alert" tabindex="-1"><strong>Zkontrolujte prosím formulář.</strong><ul><?php foreach($errors as $key=>$error):?><li><?php if($key!=='_form'):?><a href="#field-<?= $e($key) ?>"><?= $e($error) ?></a><?php else:?><?= $e($error) ?><?php endif;?></li><?php endforeach;?></ul></div><?php endif;?>
<form method="post" action="/#kontakt" enctype="multipart/form-data" id="enquiry-form"><?= $session->CSRF->renderInput() ?><input type="hidden" name="submission_token" value="<?= $e($session->craftToken) ?>"><div class="honey" aria-hidden="true"><label>Váš web<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-grid">
<?php $rules=Craft::rules($s,$s['form_mode']);foreach(Craft::fields($s['form_mode']) as $key=>[$label,$type]):if(!$rules[$key]['enabled'])continue;$required=$rules[$key]['required'];$invalid=isset($errors[$key]);$attrs='id="field-'.$key.'" name="'.$key.($type==='file'?'[]':'').'"'.($required?' required':'').($invalid?' aria-invalid="true" aria-describedby="error-'.$key.'"':'');$value=is_string($values[$key]??null)?$values[$key]:'';?><div class="form-field <?= in_array($key,['subject','message','files'])?'full':'' ?>"><label for="field-<?= $key ?>"><?= $label ?> <?= $required?'<span aria-hidden="true">*</span>':'<small>(nepovinné)</small>' ?></label>
<?php if($type==='textarea'):?><textarea <?= $attrs ?> rows="4" maxlength="10000" placeholder="Co plánujete a s čím vám můžeme pomoci?"><?= $e($value) ?></textarea><?php elseif($type==='select'):?><select <?= $attrs ?>><option value="">Vyberte typ práce</option><?php foreach(Craft::categories() as $cat):?><option <?= $value===$cat?'selected':'' ?> value="<?= $e($cat) ?>"><?= $e($cat) ?></option><?php endforeach;?></select><?php elseif($type==='file'):?><div class="upload-field"><input type="file" <?= $attrs ?> multiple accept="image/jpeg,image/png,image/webp,application/pdf"><small>JPG, PNG, WebP nebo PDF. Nejvýše 5 souborů, 10 MB na soubor a 25 MB celkem.<?= $errors?' Po opravě formuláře vyberte přílohy znovu.':'' ?></small></div><?php else:?><input type="<?= $type ?>" <?= $attrs ?> value="<?= $e($value) ?>" maxlength="<?= $key==='address'?500:200 ?>" autocomplete="<?= ['name'=>'name','phone'=>'tel','email'=>'email','address'=>'street-address'][$key]??'off' ?>"><?php endif;?><?php if($invalid):?><small class="field-error" id="error-<?= $key ?>"><?= $e($errors[$key]) ?></small><?php endif;?></div><?php endforeach;?></div><p class="privacy-note">Údaje použijeme k vyřízení vaší poptávky. <a href="/ochrana-osobnich-udaju/">Jak chráníme vaše údaje</a>.</p><button class="button form-submit" type="submit">Odeslat <?= $s['form_mode']==='quote'?'nezávaznou poptávku':'zprávu' ?> <span aria-hidden="true">↗</span></button><p class="required-note">* Povinné údaje</p></form>
